import csv

# Verify all stop_ids exist and distances are non-negative
with open('outputs/t05_clean_stops.csv', 'r', encoding='utf-8') as f:
    stops = set(row['stop_id'] for row in csv.DictReader(f))

with open('outputs/t09_poi_nearest_stop.csv', 'r', encoding='utf-8') as f:
    reader = csv.DictReader(f)
    errors = []
    for row in reader:
        if row['nearest_stop_id'] not in stops:
            errors.append(f'ERROR: stop_id {row[\"nearest_stop_id\"]} not found in t05_clean_stops.csv')
        if float(row['distance_m']) < 0:
            errors.append(f'ERROR: negative distance for {row[\"qid\"]}')

if errors:
    for e in errors:
        print(e)
else:
    print('All validations passed!')
    print(f'  - All {sum(1 for _ in csv.DictReader(open(\"outputs/t09_poi_nearest_stop.csv\", \"r\", encoding=\"utf-8\"))) - 1} POIs have valid nearest_stop_id')
    print(f'  - All distances are non-negative')
